import type { Difficulty, PromptProblem } from '../types.ts'

function q(
  id: string,
  pattern: string,
  difficulty: Difficulty,
  title: string,
  question: string | string[],
  keyPoints: string[],
  followUps: string[] = [],
): PromptProblem {
  return {
    id, track: 'knowledge', source: 'builtin', title, topic: 'Rust', pattern, difficulty, language: 'rust',
    question: Array.isArray(question) ? question : [question],
    keyPoints,
    followUps,
  }
}

/**
 * The Rust counterpart of the TypeScript & JavaScript topic: ownership and
 * the borrow checker, the trait system, error handling, smart pointers and
 * interior mutability, threads and async, unsafe and FFI, memory layout,
 * cargo and the ecosystem, testing, performance, API design, serde, web
 * services and editions. Listed only when Rust is selected.
 */
export const KNOWLEDGE_RUST: PromptProblem[] = [
  q('rust-ownership-moves', 'Ownership and borrowing', 'easy', 'Ownership, moves and borrowing',
    'Explain Rust\'s ownership model: what a move is, why a value cannot be used after it, which types are copied instead, and the two borrowing rules. Give a bug that ownership prevents and a case where it gets in the way of code that would be fine in another language.',
    [
      'Every value has exactly one owner; assigning or passing by value moves it (a bitwise copy of the struct, the source becomes unusable: E0382 "use of moved value"); the owner\'s `Drop` runs once at scope end, so there is no double free and no use after free',
      '`Copy` types (integers, floats, `bool`, `char`, shared references, tuples and arrays of Copy types) are duplicated instead of moved; a type can be Copy only if it has no `Drop` and all its fields are Copy; `Clone` is the explicit, possibly expensive duplicate',
      'Borrowing rules: any number of shared `&T` or exactly one `&mut T` at a time, and a reference may not outlive its referent; the compiler enforces "aliasing XOR mutation", which is what makes data races a compile error and iterator invalidation impossible',
      'Prevents: returning a pointer to a local, pushing to a `Vec` while iterating it, two threads mutating one value; gets in the way: a self-referential struct, a graph with parent pointers, mutating two fields through one method while a borrow of a third is live (fixes: indices, `Rc`/`Weak`, split borrows)',
      'Functions should take `&str`/`&[T]` rather than `&String`/`&Vec<T>` (deref coercion makes both callers work) and take ownership only when they need to keep the value; `Option::take` and `std::mem::take` move out of a place that must stay valid',
    ],
    ['Why can you not move out of an element of a `Vec` with `v[0]` but can with `v.remove(0)` or `v.swap_remove(0)`?', 'What does `#[derive(Clone, Copy)]` on a struct with a `String` field fail with?']),
  q('rust-borrow-checker-errors', 'Ownership and borrowing', 'medium', 'Borrow checker errors and how to restructure around them',
    'Walk through the borrow checker errors you meet most (E0502, E0499, E0505, E0597, E0716, E0507) with the shape of code that triggers each, and the standard ways to restructure: splitting borrows, computing before mutating, the entry API, indices, `take`/`replace`, cloning, or changing ownership. When is the compiler right and when is it just conservative?',
    [
      'E0502 (mutable borrow while shared borrow is live): `let first = &v[0]; v.push(x)`; since NLL (edition 2018, Rust 1.31; all editions from 1.36) a borrow ends at its last use, so reorder uses or compute the value (`let first = v[0].clone()`) before mutating',
      'E0499 (two mutable borrows): `let a = &mut v[0]; let b = &mut v[1]` fails because indexing borrows the whole `Vec`; use `split_at_mut`, `iter_mut`, `get_disjoint_mut` (1.86), destructure the struct so each field is borrowed separately, or swap to indices',
      'E0505/E0507 (move while borrowed, move out of borrow): `Option::take`, `std::mem::take`/`replace`, `Vec::drain`, `into_iter()` on an owned value, or `clone` when the data is small; E0597/E0716 (does not live long enough, temporary dropped while borrowed): bind the temporary to a `let`, return an owned value, or widen the scope',
      'The map-entry case: `if let Some(v) = map.get_mut(&k) { .. } else { map.insert(k, ..) }` is the famous conditional-return case the current checker rejects in some forms; `map.entry(k).or_insert_with(..)` is the idiom, and Polonius is the in-progress checker that accepts more of these',
      'The compiler is right about aliasing and lifetime violations; it is conservative about borrows through function calls (a method borrowing all of `self` when it touches one field) and about disjoint array indices: fix by shrinking the borrowed region (free functions on fields, smaller methods) rather than reaching for `RefCell` or `unsafe`',
    ],
    ['Why does a method taking `&mut self` that returns a reference block every other use of `self` until that reference dies?', 'When is `clone()` the right fix and when is it hiding a design problem?']),
  q('rust-lifetimes-variance', 'Ownership and borrowing', 'hard', "Lifetimes, elision, 'static and variance",
    'Explain what a lifetime annotation says and does not say, the three elision rules, what `T: \'static` means versus `&\'static T`, lifetimes on structs and impl blocks, higher-ranked trait bounds, and variance (why `&mut T` is invariant in `T`). Where do lifetimes in `impl Trait` return types trip people up?',
    [
      'A lifetime names a region of code a reference is valid for; annotations relate inputs to outputs (`fn first<\'a>(a: &\'a str, b: &str) -> &\'a str`) and never extend how long anything lives; the checker infers the shortest region satisfying all constraints',
      'Elision: each elided input lifetime gets its own parameter; if there is exactly one input lifetime it is assigned to all elided outputs; if there is a `&self`/`&mut self` its lifetime goes to the outputs; otherwise an output reference needs an explicit lifetime (E0106)',
      '`T: \'static` means "T owns no borrowed data shorter than the whole program" (a `String` satisfies it), which is why `thread::spawn` and `tokio::spawn` demand it; `&\'static str` is a reference to data living for the whole program (literals, `Box::leak`); `\'static` is a bound, not "lives forever"',
      'Variance: `&\'a T` is covariant in both (a longer-lived reference can be used where a shorter one is wanted); `&\'a mut T` is covariant in `\'a` but invariant in `T`, because otherwise you could write a short-lived reference into a long-lived slot; `Cell<T>`, `UnsafeCell<T>` and `fn(T)` arguments are invariant/contravariant, which is why `PhantomData<fn(T)>` controls variance in unsafe code',
      'HRTB `for<\'a> Fn(&\'a str) -> &\'a str` says the closure works for every lifetime, needed when the callee picks the lifetime; `struct Parser<\'a> { input: &\'a str }` ties the struct to the input, so a parser that stores `&str` cannot outlive the source and cannot be returned from the function that read the file',
      'Return-position `impl Trait`: in editions up to 2021 it captured only type parameters, so returning an iterator borrowing a parameter needed `+ \'a`; in Rust 2024 it captures all in-scope lifetimes and `use<..>` (1.82) opts out, the reverse trap: a returned `impl Iterator` now holds the borrow longer than you expected',
    ],
    ['Why is a self-referential struct unsound without `Pin` and what do the `ouroboros`/`self_cell` crates do?', 'Why does `fn f(x: &str) -> impl Fn() -> String` with the closure using `x` need `move` or `+ \'_`?']),
  q('rust-traits-generics-dyn', 'Type system', 'medium', 'Traits, generics, monomorphisation and dyn dispatch',
    'Explain traits as Rust\'s interfaces: default methods, supertraits, blanket impls, `impl Trait` in argument and return position, generic bounds, and the difference between static dispatch (monomorphisation) and `dyn Trait`. What makes a trait dyn-compatible, what is in a vtable, and how do you choose between the two?',
    [
      'A trait is a set of required and default methods; `impl Trait for Type` can live in the crate of either; blanket impls (`impl<T: Display> ToString for T`) apply to every type meeting the bound; supertraits (`trait Ord: Eq + PartialOrd`) make the subtrait imply the super',
      'Generics `fn f<T: Trait>(t: T)` and `fn f(t: impl Trait)` are monomorphised: one copy of the function per concrete type, fully inlinable, zero runtime cost, but more code and compile time; return-position `impl Trait` hides a concrete type (closures, iterators) and is still static',
      '`dyn Trait` is a fat pointer (data pointer plus vtable pointer); the vtable holds `drop_in_place`, size, align and one entry per method; a call is an indirect jump the optimiser usually cannot inline; `Box<dyn Trait>`, `&dyn Trait`, `Arc<dyn Trait + Send + Sync>`',
      'Dyn compatibility (formerly object safety): no generic methods and no methods returning `Self` unless marked `where Self: Sized`, no associated consts, no `Self: Sized` supertrait; a `dyn` type has one principal trait plus auto traits (`Send`, `Sync`) and a lifetime; trait upcasting (`&dyn Sub` to `&dyn Super`) stabilised in 1.86',
      'Choose `dyn` for heterogeneous collections (`Vec<Box<dyn Handler>>`), plugin boundaries, to cut compile time and binary size, and when the set of types is open at runtime; choose generics for hot paths, when methods are generic, and when the caller must learn the concrete type; a generic function can always be called through `dyn` if dyn-compatible, not the reverse',
      '`async fn` and `-> impl Trait` in traits are stable since 1.75 but not dyn-compatible (the return type size is unknown); use `Pin<Box<dyn Future>>` by hand, the `async-trait` crate, or `trait-variant` for a Send-bounded variant',
    ],
    ['Why does `impl Trait` in argument position not let the caller use turbofish `::<>`?', 'How large is `Box<dyn Trait>` and `&[T]`, and why does `size_of::<&dyn Trait>()` differ from `size_of::<&u8>()`?']),
  q('rust-associated-types-coherence', 'Type system', 'hard', 'Associated types, generic parameters, coherence and the orphan rule',
    'When does a trait take a generic parameter (`Add<Rhs>`) and when an associated type (`Iterator::Item`)? Explain coherence: why overlapping impls are rejected even when no type currently overlaps, what the orphan rule forbids, how the newtype pattern and `#[fundamental]` types work around it, and what GATs and const generics add.',
    [
      'Associated type: exactly one choice per implementing type (`impl Iterator for Chars { type Item = char; }`), so callers write `I::Item` without naming it; generic parameter: a type may implement the trait many times (`impl Add<Duration> for Instant`, `impl Add<i32> for Point`), at the cost of inference ambiguity; `Deref::Target` and `FromStr::Err` are associated for the same reason',
      'Coherence: for any trait and type there must be at most one impl anywhere in the program; `impl<T: Display> Foo for T` and `impl Foo for MyType` conflict even if `MyType` is not `Display`, because a downstream or future crate could add that impl (negative reasoning is not allowed except for local types and `#[fundamental]` wrappers)',
      'Orphan rule: an impl must be in the crate of the trait or of the type (with `&T`, `&mut T`, `Box<T>`, `Pin<P>` as fundamental, so `impl From<MyType> for Box<dyn Error>`-style impls on wrappers of a local type count as local); this guarantees adding an impl upstream is not a breaking change, and it is why you cannot `impl Display for Vec<u8>`',
      'Workarounds: a newtype `struct Bytes(Vec<u8>)` with `Deref` or `From`; a local extension trait (`trait VecExt { fn hex(&self) -> String }` implemented for `Vec<u8>`); feature-gated impls in the upstream crate (`serde` feature on a data crate) rather than a glue crate, which cannot exist',
      'GATs (1.65) let an associated type carry its own generics (`type Item<\'a> where Self: \'a`), enabling lending iterators; const generics (`[T; N]`, `struct Matrix<const R: usize, const C: usize>`) make array sizes part of the type, with `_` inferred const arguments in 1.89; specialisation remains unstable, so a blanket impl plus a specific one is still a conflict',
      'Trait aliases, negative impls and specialisation are all unstable, so there is no "obviously disjoint" escape hatch: `impl<T: Iterator> MyTrait for T` plus `impl MyTrait for String` is rejected because std could one day implement `Iterator for String`; the fix is a local marker trait or a newtype, and this is why a blanket impl in a public crate is a long-term commitment',
    ],
    ['Why does `impl<T: Into<String>> From<T> for MyType` conflict with the blanket `impl<T> From<T> for T`?', 'What breaks downstream if a library turns an associated type into a generic parameter?']),
  q('rust-enums-option-result-matching', 'Language semantics', 'easy', 'Enums, Option, Result and pattern matching',
    'Explain Rust enums as sum types with data, why `Option` and `Result` replace null and exceptions, how exhaustive matching, `if let`, `let else`, let chains and match ergonomics work, and what the compiler does with enum layout. What does `#[non_exhaustive]` do and why is `#[must_use]` on `Result` important?',
    [
      'An enum variant may carry a tuple or struct payload; `match` must be exhaustive, so adding a variant breaks every match without a wildcard, which is the point; patterns support ranges, `|`, `@` bindings, nested destructuring, guards and `matches!`',
      '`Option<T>` makes absence a type; `Result<T, E>` makes failure a value; the compiler cannot let you forget either, and `Result` is `#[must_use]`, so an ignored fallible call warns; combinators (`map`, `and_then`, `ok_or`, `unwrap_or_else`, `transpose`) chain without matching; `?` propagates',
      '`if let Some(x) = opt { }` for one arm; `let Some(x) = opt else { return }` (1.65) for the early-exit shape; let chains `if let Some(x) = a && x > 3 && let Ok(y) = b` stabilised in 1.88 for edition 2024 only; `while let Some(top) = stack.pop()`',
      'Match ergonomics (default binding modes) let you match `&Option<String>` with `Some(s)` and get `&String` without writing `ref`; matching on a value moves out of it unless you match on a reference or use `ref`; `as_ref()`/`as_deref()` turn `&Option<String>` into `Option<&str>`',
      'Layout: the discriminant is stored in a niche where one exists, so `Option<Box<T>>`, `Option<&T>` and `Option<NonZeroU32>` are pointer-sized and `None` is the null bit pattern (the "null pointer optimisation", relied on by FFI); `#[repr(u8)]` fixes the discriminant for C; `std::mem::discriminant` compares variants',
      '`#[non_exhaustive]` on an enum or struct forces downstream matches to include a wildcard and forbids literal construction, so you can add variants or fields without a semver-major bump; within the defining crate it has no effect',
    ],
    ['Why is `Option<Option<bool>>` one byte and `Option<u32>` eight?', 'When would you write a `match` on a tuple of two enums rather than nested `if let`s?']),
  q('rust-error-handling-design', 'Error handling', 'medium', 'Error handling design: ?, From, Box<dyn Error>, thiserror, anyhow and panics',
    'How do you design error handling across a Rust codebase? Cover how `?` desugars and uses `From`, the `std::error::Error` trait, `Box<dyn Error + Send + Sync>`, when to use `thiserror` versus `anyhow`, how to add context, and when a panic is correct. How do you report an error chain to a user and a log?',
    [
      '`?` on `Result<T, E>` returns early with `Err(From::from(e))` (via the unstable `Try` trait), so `impl From<io::Error> for MyError` lets `?` convert at each layer; on `Option` it returns `None`; mixing them in one function needs `ok_or`/`ok()`',
      'The `Error` trait (in `core` since 1.81) requires `Debug + Display` and offers `source()` for the cause chain; `Box<dyn Error + Send + Sync + \'static>` accepts any error and is fine for applications and `main() -> Result<(), Box<dyn Error>>`, but callers cannot match on it',
      'Libraries: an enum per module with `#[derive(thiserror::Error)]`, `#[error("reading {path}: {source}")]`, `#[from]` for automatic conversions, `#[source]` to chain; keep variants callers can act on, hide the rest in an opaque variant, and mark the enum `#[non_exhaustive]`',
      'Applications: `anyhow::Result<T>` (or `eyre`) with `.context("loading config")` / `.with_context(|| format!(..))`, `bail!`, `ensure!`; `anyhow::Error` is one word wide, captures a backtrace when `RUST_BACKTRACE` is set, and downcasts with `downcast_ref::<io::Error>()` when a specific error must be handled',
      'Panic for bugs and broken invariants (`unreachable!`, index out of bounds, `expect("config validated at startup")`), never for expected failures; `unwrap` is fine in tests and prototypes, a lint target in services (`clippy::unwrap_used`); `panic = "abort"` in the release profile removes unwinding; `catch_unwind` is for isolating a thread or FFI boundary, not control flow',
      'Report by walking `source()` (anyhow\'s `{:#}` prints "a: b: c", `{:?}` adds the backtrace); log once at the boundary with structured fields; map to HTTP status or exit code there; never `format!("{}", e)` at every layer or the chain duplicates',
    ],
    ['Why is `Box<dyn Error>` not `Send`, and when does that bite you?', 'How do you keep a `thiserror` enum from leaking a dependency\'s error type into your public API?']),
  q('rust-smart-pointers-interior-mutability', 'Memory and performance', 'medium', 'Smart pointers and interior mutability: Box, Rc/Arc, Cell/RefCell, Mutex/RwLock, Weak',
    'Compare `Box`, `Rc`, `Arc`, `Cell`, `RefCell`, `Mutex`, `RwLock`, `OnceLock`/`LazyLock` and `Weak`: what each gives up, which are thread-safe, and what interior mutability means. Give the runtime failure each can cause and the pattern (`Rc<RefCell<T>>`, `Arc<Mutex<T>>`) each belongs to.',
    [
      '`Box<T>`: single owner, heap allocation, the way to build recursive types and `dyn Trait` values; no runtime cost beyond the allocation; `Box<[T]>`/`Box<str>` save a word over `Vec`/`String` when the length is fixed',
      '`Rc<T>`: shared ownership with a non-atomic count, `!Send`, `clone` is a counter bump; `Arc<T>`: atomic counts, `Send + Sync` when `T: Send + Sync`; both give only `&T`, so mutation needs an interior-mutability wrapper; cycles leak, which `Weak<T>` (`Rc::downgrade`, `upgrade() -> Option<Rc<T>>`) breaks for parent and observer pointers',
      'Interior mutability: mutate through `&T` by moving the aliasing check to runtime; everything is built on `UnsafeCell`, the only legal way to get `&mut` from `&`; `Cell<T>` for `Copy`-like values (`get`/`set`/`replace`, no references out, never panics); `RefCell<T>` hands out `Ref`/`RefMut` guards and panics with "already borrowed: BorrowMutError" on a conflict (`try_borrow_mut` to avoid it); both `!Sync`',
      '`Mutex<T>` (futex-based on Linux since 1.62) and `RwLock<T>` are the `Sync` equivalents: `lock()` returns a `MutexGuard` that unlocks on drop and is `!Send`; a panic while holding the lock poisons it (`PoisonError`, `into_inner()` recovers); `RwLock` writer fairness is platform-dependent; `parking_lot` offers smaller, unpoisoned locks',
      '`OnceLock`/`OnceCell` (1.70) for set-once globals, `LazyLock`/`LazyCell` (1.80) for lazily initialised statics replacing `lazy_static`/`once_cell`; `Arc<Mutex<T>>` for shared mutable state across threads, `Rc<RefCell<T>>` within one thread, and both are a smell when the design could pass ownership or use channels instead',
      'Failure modes: `RefCell` double borrow at runtime (often from a callback re-entering), deadlock from locking the same `Mutex` twice (not reentrant) or holding a guard across a call that locks again, `Rc` cycles leaking, `Arc<Mutex<T>>` contention serialising a hot path (shard it, or use atomics/`RwLock`/`DashMap`)',
    ],
    ['Why is `MutexGuard` not `Send`, and what does that mean for holding it across an `.await`?', 'What does `Arc::make_mut` do and how does it give copy-on-write?']),
  q('rust-send-sync', 'Concurrency', 'hard', 'Send, Sync and fearless concurrency',
    'Explain the `Send` and `Sync` marker traits: how they are inferred, what makes a type fail each, how `Arc<T>: Send` depends on `T`, why `Rc`, `RefCell`, `MutexGuard` and raw pointers are excluded, and how they let the compiler reject data races. When is `unsafe impl Send` justified, and how do you read a "future cannot be sent between threads" error?',
    [
      '`Send`: ownership can move to another thread; `Sync`: `&T` can be shared across threads, i.e. `T: Sync` iff `&T: Send`; both are auto traits implemented for a type when all its fields implement them, so most types are both without any code',
      'Excluded: `Rc<T>` (non-atomic counts, `!Send + !Sync`), `Cell`/`RefCell` (unsynchronised interior mutability: `Send` but `!Sync`), `MutexGuard` (must unlock on the locking thread: `!Send`), `*const T`/`*mut T` (the compiler cannot know what they alias: neither), `NonNull`; a type containing any of these inherits the exclusion',
      '`Arc<T>: Send + Sync` requires `T: Send + Sync`, because clones on several threads can all reach `&T`; `Mutex<T>: Sync` requires only `T: Send`, which is how `Arc<Mutex<Rc<..>>>` is still rejected but `Arc<Mutex<Vec<T>>>` works; `thread::spawn` requires `F: Send + \'static`, so the closure\'s captures must all be `Send`',
      'Data-race freedom follows: a data race needs two threads with unsynchronised access to one place, which needs either sharing a `!Sync` type or sending a `!Send` one; safe Rust can create neither, so a race is only possible through `unsafe`; deadlocks, livelocks and logical races (check-then-act) remain your problem',
      '`unsafe impl Send for MyType {}` is a promise that the raw pointer or FFI handle inside is safe to move; justified for a handle whose C library documents thread-safety, wrong for GUI toolkits and OpenGL contexts; `PhantomData<*const ()>` or `PhantomData<Rc<()>>` opts a type out deliberately; negative impls (`impl !Send`) are unstable',
      'The async error "future cannot be sent between threads safely" means a `!Send` value (a `std::sync::MutexGuard`, `Rc`, `RefCell` borrow, `Cell`) is held across an `.await`; the note names the type and the await point; fix by dropping or scoping the value before `.await`, using `tokio::sync::Mutex`, or `spawn_local` on a `LocalSet`',
    ],
    ['Why is `Cell<T>` `Send` but not `Sync`, while `AtomicUsize` is both?', 'How does `std::thread::scope` let you share a `&mut Vec<T>` between threads without `Arc` or `Mutex`?']),
  q('rust-threads-channels-atomics', 'Concurrency', 'medium', 'Threads, channels, scoped threads, atomics and memory ordering',
    'Describe the standard-library concurrency toolkit: `thread::spawn` and `JoinHandle`, `thread::scope`, `mpsc` channels, `Condvar`, `Barrier`, and atomics with their orderings. Which ordering do you use for a counter, for publishing a value, and when do you need `SeqCst`? Where do `rayon` and `crossbeam` come in?',
    [
      '`thread::spawn(f)` needs `F: FnOnce + Send + \'static`; `JoinHandle::join()` returns `Result<T, Box<dyn Any + Send>>`, the `Err` being a panic payload, so panics are propagated not lost; default stack is 2 MiB (`RUST_MIN_STACK`, `thread::Builder::stack_size`); `available_parallelism()` for sizing pools',
      '`thread::scope` (1.63): spawned threads may borrow from the enclosing stack because the scope joins them all before returning (a panic in one propagates after joining); this replaces `crossbeam::scope` and removes most `Arc` in fork-join code; `rayon` builds `par_iter` and `join` work stealing on the same idea',
      'Channels: `std::sync::mpsc::channel` (unbounded) and `sync_channel(n)` (bounded, backpressure), `Sender: Clone`, one `Receiver`; since 1.67 the implementation is crossbeam\'s; `recv` returns `Err` when all senders drop, which is the shutdown signal; `crossbeam-channel` adds `select!` and MPMC, `flume` likewise',
      'Atomics (`AtomicUsize`, `AtomicBool`, `AtomicPtr`, `AtomicU64` where `target_has_atomic = "64"`) follow the C++20 model: `Relaxed` for counters and statistics (atomicity only), `Release` on the store and `Acquire` on the load to publish data written before the store (the pattern inside `Arc::drop`, spinlocks, `OnceLock`), `AcqRel` for read-modify-write, `SeqCst` only when several atomics must appear in one global order (rare; Mara Bos\'s book is the reference)',
      '`compare_exchange(old, new, success, failure)` returns `Result<prev, actual>`; `compare_exchange_weak` may fail spuriously and is right inside a retry loop; `fetch_add`/`fetch_update`; `hint::spin_loop()` in spin loops; `Condvar::wait_while` handles spurious wakeups; `Barrier` for phases; `Mutex` plus `Condvar` is the usual work queue before reaching for lock-free code',
      'Testing concurrent code: `loom` explores interleavings of a model under the C11 memory model, Miri detects data races in `unsafe` code, `cargo test` runs tests on parallel threads so shared `static`s and `set_var` (unsafe in 2024) cause flakes; deadlock diagnosis is a stack dump (`gdb`/`lldb`), there is no built-in detector',
    ],
    ['Why would you choose a bounded channel over an unbounded one for a pipeline?', 'What goes wrong if you use `Relaxed` for the flag that says "data is ready"?']),
  q('rust-async-model', 'Async', 'hard', 'Async Rust: futures, Pin, wakers and executors',
    'Explain how `async fn` compiles to a state machine, the `Future` trait and `poll`, why futures are lazy, what `Pin` is for and why `poll` takes `Pin<&mut Self>`, how wakers connect a leaf I/O future to the reactor, and what an executor like tokio does. Why does Rust have no built-in runtime, and what does that cost?',
    [
      '`async fn f() -> T` returns an anonymous type implementing `Future<Output = T>`; the compiler turns the body into an enum with one state per `.await` point holding the live locals; nothing runs until something polls it, so `let f = fetch();` without `.await` does no I/O (`#[must_use]` warns)',
      '`trait Future { type Output; fn poll(self: Pin<&mut Self>, cx: &mut Context<\'_>) -> Poll<Self::Output>; }`; `poll` returns `Ready(v)` or `Pending`, and a future returning `Pending` must have arranged for `cx.waker().wake()` to be called later or it will never be polled again (the classic hang)',
      'Wakers: a leaf future (a socket read in tokio, built on `mio` over epoll/kqueue/IOCP) registers interest plus the waker with the reactor and returns `Pending`; when the OS reports readiness the reactor wakes the task, the executor re-polls the whole task tree, and intermediate futures forward the poll to whichever child is not ready',
      '`Pin<P>` promises the pointee will not move until dropped; the state machine stores references across await points to its own locals, so moving it would dangle them; `poll` takes `Pin<&mut Self>` to make that promise; most types are `Unpin` (moving is fine), `!Unpin` ones (generated futures, `PhantomPinned`) need `Box::pin`, `pin!` (1.68) or a `pin_project`ed field to be polled',
      'An executor owns tasks, polls them when woken, and parks the thread otherwise: tokio multi-thread uses work-stealing worker threads plus a reactor and timer wheel; `current_thread` runs everything on one thread; `smol`/`async-executor` is small; `embassy` targets microcontrollers with no allocation; `async-std` was discontinued in 2025 in favour of `smol`',
      'No built-in runtime because embedded, kernel and server needs differ, so `std` provides only the `Future` trait, `Waker`, `Pin` and (as of 1.85) async closures and `AsyncFn*` traits; the cost is ecosystem splits (`tokio::io::AsyncRead` vs `futures::io::AsyncRead`, `Stream` still outside std), runtime-specific crates, and `#[tokio::main]` wiring in every binary',
    ],
    ['Why must a hand-written `Future` not call `wake()` and then return `Ready` in a loop, and what is tokio\'s cooperative budget for?', 'What makes a `Stream` different from an `Iterator` and why is `for await` not in the language?']),
  q('rust-async-in-practice', 'Async', 'medium', 'Async in practice: tokio, Send bounds, cancellation and blocking',
    'A tokio service is slow and sometimes hangs. Explain the practical rules: `tokio::spawn` and `Send + \'static`, `std::sync::Mutex` versus `tokio::sync::Mutex`, what happens when a handler blocks the thread, `spawn_blocking`, how cancellation works by dropping a future, `select!` and cancellation safety, timeouts, `JoinSet`, and how you would find the hang.',
    [
      '`tokio::spawn(fut)` requires `fut: Send + \'static` because the task may migrate between workers; holding `Rc`, a `RefCell` borrow or a `std::sync::MutexGuard` across `.await` breaks `Send`; a task is detached on drop of its `JoinHandle` (`abort()` cancels it), `JoinSet` aborts all on drop and gives structured join',
      'Locks: use `std::sync::Mutex` when the critical section has no `.await` (cheaper, and the guard must not cross an await); `tokio::sync::Mutex` when you must hold it across an await, accepting a slower, fair, async lock; prefer message passing (`mpsc`, `watch`, `oneshot`, `broadcast`) or sharding over a hot async mutex',
      'Blocking inside a task (sync `std::fs`, `reqwest::blocking`, a CPU loop, `std::thread::sleep`) stalls one of the N worker threads and every task queued on it; move it to `spawn_blocking` (a separate pool, default up to 512 threads), `block_in_place`, or a `rayon` pool with a `oneshot` back; tokio warns in debug builds and `tokio-console` shows tasks with long polls',
      'Cancellation is dropping the future: a task stops only at its next `.await`, destructors run, no code after the await runs; `tokio::time::timeout(d, fut)` and `select!` cancel the losing branches, so a branch that has read half a message from a socket loses it unless the future is "cancellation safe" (tokio documents which are; `recv()` is, `read_exact` is not); `CancellationToken` (tokio-util) for cooperative shutdown',
      'Hang diagnosis: a future that returned `Pending` without a waker (hand-written or a misused `Notify`), a deadlock between `tokio::sync::Mutex` locks, a bounded channel whose receiver was dropped or never read, `block_on` called inside the runtime (panics), or an uncompleted `JoinHandle` awaited after the task panicked; `tokio-console`, `tracing` spans with `#[instrument]`, and `RUSTFLAGS="--cfg tokio_unstable"` task dumps',
      'Fan-out: `join!`/`try_join!` for a fixed set, `JoinSet` or `futures::stream::FuturesUnordered` plus `buffer_unordered(n)` for bounded concurrency, `Semaphore` for admission control; never `for item in items { item.process().await }` when you wanted parallelism, and never unbounded `spawn` per request without a limit',
    ],
    ['Why does `async fn` in a trait object need boxing, and what does `#[async_trait]` generate?', 'How would you test a timeout-heavy module without waiting (`tokio::test(start_paused = true)`, `time::pause`)?']),
  q('rust-iterators-closures', 'Language semantics', 'medium', 'Iterators, closures and zero-cost abstractions',
    'Explain the `Iterator` trait and lazy adapters, `IntoIterator` and the three `iter` methods, how `collect` is generic over `FromIterator`, and closures: capture modes, `move`, the `Fn`/`FnMut`/`FnOnce` hierarchy and when each is required. Why does an iterator chain compile to the same code as a hand loop, and when does it not?',
    [
      '`trait Iterator { type Item; fn next(&mut self) -> Option<Self::Item>; }` plus about seventy provided methods; adapters (`map`, `filter`, `take_while`, `zip`, `enumerate`, `flat_map`, `peekable`, `windows`/`chunks` on slices) are lazy structs wrapping the source; consumers (`sum`, `fold`, `try_fold`, `count`, `collect`, `for_each`, `any`) drive `next`',
      '`for x in c` calls `IntoIterator::into_iter(c)`: `iter()` yields `&T`, `iter_mut()` `&mut T`, `into_iter()` `T` and consumes the collection; since edition 2021 arrays implement `IntoIterator` by value; `collect::<Vec<_>>()`, `collect::<HashMap<_, _>>()`, `collect::<Result<Vec<_>, E>>()` (stops at the first `Err`), `String` from `char`s all go through `FromIterator`; `size_hint` lets `collect` preallocate',
      'Closures capture each variable by the least permissive mode the body needs (shared ref, mutable ref, or move), and since edition 2021 capture disjoint fields rather than whole structs; `move` forces by-value capture, required to return a closure or send it to a thread; a closure is `Copy`/`Clone` when its captures are',
      '`FnOnce` (may consume captures, callable once: `thread::spawn`, `Option::unwrap_or_else`), `FnMut` (mutates captures: `for_each`, `sort_by`), `Fn` (only reads: callbacks stored in `Arc`, called concurrently); every `Fn` is `FnMut` is `FnOnce`; take `impl FnMut(T) -> U` as a parameter for flexibility, store `Box<dyn Fn(T) -> U + Send + Sync>` for dynamic callbacks; function items and non-capturing closures coerce to `fn` pointers',
      'Zero-cost: each adapter is a distinct monomorphised struct whose `next` inlines into the consumer, so `v.iter().map(f).filter(g).sum()` compiles to one loop without bounds checks (the iterator knows its length), often auto-vectorised; `chunks_exact` and `zip` on slices eliminate checks where indexing would not',
      'Where it is not free: `dyn Iterator` boxes (one indirect call per item), `flatten` and `chain` defeat some vectorisation, `collect` into intermediate `Vec`s between stages, `rev()` on a `chars()` iterator (UTF-8 decoding backwards), and closures stored as `Box<dyn Fn>` in hot loops; `cargo asm`/Godbolt confirm',
    ],
    ['Why can an `Iterator` not yield references into the collection it owns (what GATs change)?', 'What does `Iterator::by_ref` do and when do you use it?']),
  q('rust-strings-utf8', 'Language semantics', 'easy', 'Strings, slices, UTF-8: str versus String',
    'Explain `String`, `&str`, `str`, `[u8]`, `char` and the conversions between them, why `s[0]` does not compile and `&s[0..3]` can panic, what `len()` counts, how to iterate, and the other string types (`OsStr`, `CStr`, `Path`). How do you build strings efficiently and when do you use `Cow<str>`?',
    [
      '`String` is a growable, owned `Vec<u8>` guaranteed valid UTF-8; `str` is the unsized slice type, so you hold `&str` (pointer plus byte length, a fat pointer) or `Box<str>`/`Rc<str>`; `&String` derefs to `&str`, so functions take `&str`; a literal is `&\'static str`',
      'No integer indexing because a byte index is not a character and O(1) character access is impossible in UTF-8; range slicing `&s[a..b]` works in bytes and panics when `a` or `b` is not a char boundary (`is_char_boundary`, `get(a..b)` returns `None` instead); `len()` and `capacity()` are bytes, `chars().count()` is scalar values, and user-perceived characters (grapheme clusters, e.g. an emoji with modifiers) need the `unicode-segmentation` crate',
      '`char` is a 4-byte Unicode scalar value; `chars()` decodes on the fly, `bytes()` is free, `char_indices()` gives byte offsets for slicing; `to_lowercase()` returns a `String` because the length may change (ß to ss); comparisons are bytewise, so case-insensitive or locale-aware ordering needs `unicase`/`icu`',
      'Conversions: `String::from_utf8(vec) -> Result` validates, `from_utf8_lossy` returns `Cow<str>` with U+FFFD replacements, `from_utf8_unchecked` is `unsafe` and invalid UTF-8 in a `str` is undefined behaviour; `as_bytes()`, `into_bytes()`; `OsString`/`OsStr` for environment and file names that may not be UTF-8 (WTF-8 on Windows), `Path`/`PathBuf` wrap them, `CString`/`CStr` for NUL-terminated FFI, `c"literal"` since 1.77',
      'Building: `String::with_capacity`, `push_str`, `write!(s, ..)` (`std::fmt::Write`) rather than `s += &format!(..)` in loops; `format!` allocates once; `join` on a `Vec<&str>`; `Cow<\'a, str>` returns a borrowed `&str` when no change was needed and an owned `String` otherwise (`fn normalise(s: &str) -> Cow<str>`), avoiding allocation on the common path; `bytes::Bytes` for shared, reference-counted byte slices in network code',
    ],
    ['Why does `&s[..1]` on "é" panic, and what should the code have done?', 'When is `Box<str>` better than `String` in a struct?']),
  q('rust-collections', 'Collections', 'medium', 'Collections: Vec growth, HashMap hashing, BTreeMap and the entry API',
    'Explain how `Vec` grows, what `HashMap` uses for hashing and why, when `BTreeMap` beats it, how the entry API avoids double lookups, and how `VecDeque`, `BinaryHeap` and `HashSet` fit. What are the `Hash`/`Eq` contract and the sort guarantees?',
    [
      '`Vec<T>` is pointer, capacity, length (three words); `push` doubles capacity when full (minimum 4 for small elements), so appends are amortised O(1); `with_capacity` avoids reallocation, `shrink_to_fit` gives memory back, `swap_remove` is O(1) where `remove` is O(n), `drain(..)` and `retain` edit in place, `extend_from_slice` memcpy for `Copy` types',
      '`HashMap<K, V>` is hashbrown\'s SwissTable (since 1.36) with SipHash-1-3 keyed by a random `RandomState` per map: HashDoS-resistant but slower than needed for small keys; swap with `with_hasher` to `FxHash`/`rustc-hash` (compilers, trusted keys) or `ahash`; iteration order is unspecified and differs run to run, so tests must sort; `IndexMap` keeps insertion order',
      '`BTreeMap` (B = 6, nodes of 5 to 11 entries, cache-friendly) keeps keys sorted: `range(a..b)`, `first_key_value`, `last_entry`, ordered iteration, deterministic output, and it needs only `Ord`, not `Hash`; O(log n) versus O(1) expected, so it wins for range queries, small maps and when order matters, and for keys like floats that cannot be `Eq`',
      'Entry API: `map.entry(k).or_insert_with(Vec::new).push(v)`, `.or_default()`, `.and_modify(|c| *c += 1).or_insert(1)`; one hash and probe instead of `get` then `insert`, and it solves the borrow-checker shape where `get_mut` followed by `insert` is rejected; `HashMap::get` accepts `&Q where K: Borrow<Q>`, so `map.get("key")` works on `HashMap<String, _>`',
      '`VecDeque` ring buffer for queues and sliding windows (`push_back`/`pop_front` O(1), `make_contiguous`), `BinaryHeap` max-heap (`Reverse` for min, `peek`, `into_sorted_vec`), `HashSet`/`BTreeSet` with `intersection`/`difference`; `sort` is stable (driftsort since 1.81), `sort_unstable` (ipnsort) is faster, `sort_by_key`/`sort_by_cached_key`, `select_nth_unstable`, `binary_search` on sorted data, `dedup` after sorting',
      'Contract: `k1 == k2` must imply equal hashes; a key must not change while in the map (keys are immutable by API); `Hash` and `Eq` derived together; `f64` is `PartialOrd` only, so sort with `total_cmp` or `ordered-float`; `Vec<Box<dyn Trait>>` for heterogeneous items, `SmallVec`/`ArrayVec` to avoid heap for short lists',
    ],
    ['Why is a `HashMap` with `u64` keys often slower than a `Vec` indexed by id, and when does that change?', 'What does `Vec::into_boxed_slice` save and when is it worth it?']),
  q('rust-unsafe-ffi-soundness', 'Unsafe and FFI', 'hard', 'Unsafe Rust, FFI and soundness',
    'What does the `unsafe` keyword permit, what is undefined behaviour in Rust, and what does it mean for an API to be sound? Walk through an FFI boundary (`extern "C"`, `#[repr(C)]`, ownership of memory across the boundary, panics) and the tools (Miri, sanitizers, `bindgen`, `cxx`) and conventions (`// SAFETY:` comments) you use.',
    [
      '`unsafe` unlocks five things: dereferencing raw pointers, calling `unsafe fn`s (including FFI), reading or writing `static mut`, implementing `unsafe trait`s (`Send`, `Sync`, `GlobalAlloc`), and accessing `union` fields; it does not turn off the borrow checker or type checking; `unsafe fn` declares preconditions, `unsafe {}` asserts you met them',
      'UB includes data races, dereferencing dangling or unaligned pointers, creating two live `&mut` to one place or a `&mut` from a `&`, producing invalid values (a `bool` of 2, a null `NonNull`/`&T`, invalid UTF-8 in `str`, an uninhabited enum), reading uninitialised memory (use `MaybeUninit`), and unwinding across `extern "C"` (`extern "C-unwind"`, 1.81, allows it); the optimiser assumes none of these happen, so UB is not "a crash" but miscompilation',
      'Soundness: a safe API must make UB impossible for any safe caller, however adversarial; a `pub fn` that can be misused into UB is a soundness bug even if nobody does; the aliasing model (Stacked Borrows, now Tree Borrows) is what Miri checks, so `cargo +nightly miri test` runs the tests under an interpreter that reports UB; `-Zsanitizer=address,thread` on nightly for compiled code; `unsafe_op_in_unsafe_fn` warns in edition 2024 so every operation gets its own block',
      'FFI: `unsafe extern "C" { fn strlen(s: *const c_char) -> usize; }` (blocks are `unsafe extern` in 2024, with `safe fn` items for known-safe functions); `#[repr(C)]` on structs and enums for a defined layout; `#[unsafe(no_mangle)] pub extern "C" fn` to export; `std::ffi::{c_int, CStr, CString}`; `bindgen` generates bindings from headers, `cbindgen` headers from Rust, `cxx` a checked C++ bridge, `pyo3`/`napi-rs`/`uniffi` for higher-level targets',
      'Ownership across the boundary: whoever allocated frees; hand C a `Box::into_raw` pointer and take it back with `Box::from_raw` exactly once; never free a `CString` with C `free` (`CString::into_raw`/`from_raw`); callbacks need `extern "C" fn` plus a `*mut c_void` user-data pointer, and a panic inside them must be caught with `catch_unwind` before it crosses; lifetimes of borrowed C data are invisible to Rust, so wrap handles in a struct with `Drop` and `PhantomData`',
      'Conventions: minimise the `unsafe` surface, document each block with `// SAFETY:` stating which preconditions hold and why, encapsulate behind a safe module boundary with invariants in the type (`NonNull`, `NonZero`, newtypes), prefer `std::ptr::read`/`write`, `slice::from_raw_parts` with checked lengths, `&raw const`/`&raw mut` (1.82) instead of `&x as *const _`; `#![forbid(unsafe_code)]` in crates that need none',
    ],
    ['Why is `mem::transmute::<&[u8], &str>` unsound even if you checked the bytes, compared with `str::from_utf8_unchecked`?', 'What does `static mut` get you that `AtomicUsize`, `Mutex` or `OnceLock` in a `static` do not, and why does edition 2024 deny references to it?']),
  q('rust-memory-layout-drop', 'Memory and performance', 'medium', 'Memory layout, Drop and RAII, Copy versus Clone, repr',
    'Explain how Rust lays out structs and enums (`repr(Rust)` reordering, padding, niches), what `repr(C)`, `repr(transparent)` and `repr(u8)` change, how and when `Drop` runs (order, moves, partial moves, `mem::forget`), RAII guards, and the exact difference between `Copy` and `Clone`. How do you measure and shrink a type?',
    [
      '`repr(Rust)` (the default) lets the compiler reorder fields to minimise padding and use niches, so field order in source does not fix layout and two structurally identical structs may differ; `size_of::<T>()`, `align_of::<T>()`, `size_of_val`; size is always a multiple of alignment; `(u8, u32, u8)` is 8 bytes in Rust and 12 in C order',
      '`#[repr(C)]` fixes C order and padding for FFI and for `unsafe` casts between types; `#[repr(transparent)]` makes a single-field newtype ABI-identical to its field (`struct Fd(c_int)` can cross FFI); `#[repr(u8)]`/`#[repr(i32)]` fixes an enum\'s discriminant size and allows `as` casts; `#[repr(packed)]` removes padding and makes references to fields unsound (use `addr_of!`); `#[repr(align(64))]` for cache-line padding',
      'Niches: `Option<&T>`, `Option<Box<T>>`, `Option<NonZeroU64>` cost no extra byte; a `bool` has 254 niche values so `Option<bool>` is one byte; `Result<(), Box<dyn Error>>` is two words; `Box<dyn Trait>` and `&[T]` are two words (fat), `Vec<T>` three, `String` three, `Rc<T>` one (counts live in the allocation); ZSTs (`()`, `PhantomData`) take zero bytes and `Vec<()>` never allocates',
      '`Drop` runs when the owner goes out of scope (locals in reverse declaration order, then struct fields in declaration order, then each element of a `Vec`), when overwritten by assignment, or via `drop(x)`; a moved-from binding does not drop; partially moved structs drop the remaining fields; `mem::forget` and `Box::leak` skip it safely (leaks are not UB), `ManuallyDrop` controls it; `Drop::drop` cannot be called directly and a type implementing `Drop` cannot be `Copy` or have fields moved out of it',
      'RAII: `MutexGuard`, `File`, `TcpStream`, `tempfile`, scope guards (`scopeguard::defer!`) release in `drop`, including during unwinding, so cleanup cannot be forgotten; drop cannot fail or be async (no async drop yet), so a type whose cleanup can fail needs an explicit `close(self) -> Result` plus a best-effort `Drop`',
      '`Copy` is a marker trait: the compiler duplicates the bits and the source stays valid, allowed only when every field is `Copy` and there is no `Drop`; `Clone` is a method you call, may allocate, and `Copy: Clone` so a `Copy` type\'s `clone()` is a bitwise copy; derive `Copy` for small plain data (ids, points, enums without payload), not for anything holding a `Vec`/`String`/`Box`; measure with `size_of`, `cargo-show-asm`, `-Zprint-type-sizes` on nightly, and shrink by reordering is automatic, by boxing large rare variants (`clippy::large_enum_variant`) and by `u32` indices in place of pointers',
    ],
    ['Why does a `struct Guard<\'a>(&\'a mut State)` with `Drop` sometimes cause "borrow does not live long enough" that goes away without `Drop` (drop check)?', 'What is the layout difference between `Vec<Option<u32>>` and `Vec<Option<NonZeroU32>>` and when does it matter?']),
  q('rust-modules-cargo-semver', 'Modules and tooling', 'medium', 'Modules, crates, cargo, features, workspaces, semver and MSRV',
    'Explain the module system (`mod`, visibility, paths, `pub use` facades), what a crate and a package are, how cargo resolves versions (semver caret rules, `Cargo.lock`, several versions of one crate), how features work and why they must be additive, what a workspace shares, and how `rust-version` and the MSRV-aware resolver interact.',
    [
      '`mod foo;` loads `foo.rs` or `foo/mod.rs`; items are private to their module and descendants by default, `pub`, `pub(crate)`, `pub(super)`, `pub(in path)`; paths start at `crate::`, `self::`, `super::` or an external crate (2018 path clarity); `pub use` re-exports build a flat public API independent of the file tree; `lib.rs` plus `main.rs` in one package lets the binary and integration tests use the library',
      'A package (one `Cargo.toml`) has at most one library crate and any number of binaries, examples, tests and benches; a crate is the compilation unit, compiled as one translation unit with `codegen-units` splitting it for parallel LLVM; crates in a build graph can use different editions',
      'Semver in cargo: `"1.2.3"` means `^1.2.3` (`>=1.2.3, <2.0.0`), while `0.2.3` means `<0.3.0` because the leading zero makes the minor the breaking version; `=`, `~`, `>=` exist; `Cargo.lock` pins exact versions and is now committed for libraries too; two semver-incompatible versions of one crate coexist in a build, which is why `expected foo::Bar, found foo::Bar` happens; `cargo tree -d` finds duplicates, `cargo update -p x --precise 1.2.3` pins, `[patch.crates-io]` overrides',
      'Features are boolean, unified across the whole build graph (if any dependency enables `serde` on `uuid`, everyone gets it), so they must be additive: never a `no_std` feature, always a default `std` one; `default-features = false`, `optional = true` creating an implicit feature, `dep:` syntax to hide it (1.60), `foo?/bar` weak dependency features; test combinations with `cargo hack --feature-powerset` because `cargo test` only sees one unification',
      'Workspaces: one `Cargo.lock` and `target/` for all members; `[workspace.dependencies]` and `[workspace.package]` with `x.workspace = true` to inherit versions, edition and lints (`[lints]` table, 1.74); resolver `"2"` (default from edition 2021) stops dev and build dependency features leaking into normal builds; resolver `"3"` (default in edition 2024, 1.84) is MSRV-aware',
      '`rust-version = "1.75"` declares the MSRV: cargo refuses to build on older compilers with a clear message and the MSRV-aware resolver prefers dependency versions compatible with it; verify in CI with the pinned toolchain (`rust-toolchain.toml`), `cargo-semver-checks` catches accidental breaking changes before `cargo publish`, `cargo audit`/`cargo deny`/`cargo vet` cover advisories, licences and supply chain',
    ],
    ['Why is adding a variant to a public enum a breaking change but adding a method to a struct usually not, and what about adding a trait impl?', 'What is wrong with a `no-default-features`-only test matrix?']),
  q('rust-macros', 'Macros', 'medium', 'Macros: macro_rules! and procedural macros',
    'Explain declarative macros (`macro_rules!`): fragment specifiers, repetitions, hygiene, `$crate` and recursion. Then procedural macros: the three kinds, why they live in their own crate, how `syn`/`quote`/`proc_macro2` are used, and their cost. When is a macro the right tool over a generic function or a trait?',
    [
      '`macro_rules!` matches token trees against arms: `($($key:expr => $val:expr),* $(,)?) => { .. }`; fragments `expr`, `ty`, `ident`, `pat`, `tt`, `literal`, `block`, `path`, `vis`, `lifetime`, `meta` (and `expr_2021` for the old `expr` meaning in edition 2024); `$( .. )*`, `+`, `?` repetitions must nest the same depth in pattern and expansion; the first matching arm wins and matching does not backtrack across fragments',
      'Hygiene is partial: local variables introduced by the macro cannot clash with the caller\'s (`let` in a macro is invisible outside), but items, paths and fields are not hygienic, so macros refer to their own crate as `$crate::path` and users must have traits in scope unless the macro names them fully; `#[macro_export]` puts the macro at the crate root; `recursion_limit` caps recursive expansions',
      'Procedural macros are compiler plugins: function-like `name!(..)`, derive `#[derive(Name)]` (adds items, cannot change the input), attribute `#[name(..)]` (replaces the item); they must be in a crate with `proc-macro = true`, compiled for the host and run at compile time, so they cannot be unit-tested like normal code and need a `_derive` companion crate re-exported by the facade (`serde` + `serde_derive`)',
      'Pipeline: receive a `proc_macro::TokenStream`, parse with `syn` (`parse_macro_input!(input as DeriveInput)`), build output with `quote! { impl #name { .. } }` interpolating `#ident` and `#(#fields),*`, return it; `proc_macro2` makes the types usable in tests; errors via `syn::Error::to_compile_error()` with spans so the message lands on the user\'s code; `cargo expand` shows the result',
      'Cost: `syn` with `full` features is often the heaviest build dependency; every derive runs on every compile of the crate; heavy macros bloat `cargo check` time; keep generated code small and delegate to a generic runtime function (the `serde` approach), avoid parsing when `macro_rules!` would do, and consider `#[derive]` only where the trait really depends on the struct\'s shape',
      'Right tool: `macro_rules!` for variadic-like calls (`vec!`, `println!`, test tables), repeating impls over primitive types, DSL-ish syntax; derive macros for shape-dependent traits (`Serialize`, `Debug`, `thiserror::Error`, `clap::Parser`); wrong tool when a generic function, a trait with a blanket impl, `const fn` or a build script expresses it, because macros hide types from rust-analyzer, produce worse errors and resist refactoring',
    ],
    ['Why does a `macro_rules!` macro that takes `$e:expr` fail to match `a => b` but one taking `$t:tt` can?', 'How do you write a derive macro that produces a helpful error on an unsupported enum instead of a panic?']),
  q('rust-testing-benchmarking', 'Testing', 'medium', 'Testing and benchmarking: unit, integration and doc tests, proptest, criterion',
    'Describe how testing is organised in a Rust project: `#[cfg(test)]` unit tests, integration tests in `tests/`, doc tests, `#[should_panic]`, async tests, how the harness runs them in parallel, and what `cargo nextest` adds. Then property tests with `proptest`, fuzzing, snapshot testing, and benchmarking with `criterion` (and why `#[bench]` is not the answer).',
    [
      'Unit tests sit in the same file under `#[cfg(test)] mod tests` and can test private items; `#[test] fn x() -> Result<(), E>` lets tests use `?`; `#[should_panic(expected = "..")]`, `#[ignore]` with `cargo test -- --ignored`; `assert_eq!` prints both sides, `pretty_assertions` diffs; `#[tokio::test]` for async, with `flavor = "multi_thread"` or `start_paused = true` to fast-forward timers',
      'Integration tests: each `tests/*.rs` file is its own crate linking the library only (binaries are tested through `assert_cmd` or by moving logic into `lib.rs`); shared helpers go in `tests/common/mod.rs`, not `tests/common.rs` which would be its own test crate; `cargo test --test name`, `--lib`, `--doc`, a substring filter, `-- --nocapture`, `--test-threads=1`',
      'Doc tests: code blocks in `///` comments compile and run with `cargo test --doc`; `# ` hides setup lines, `no_run`, `ignore`, `should_panic`, `compile_fail` annotate; each was a separate binary and slow until edition 2024 merged them into one; they are the only tests that guarantee examples in docs still compile',
      'The libtest harness runs tests on parallel threads in one process, so tests sharing a `static`, environment variables, the working directory or a port flake; `cargo nextest` runs each test in its own process with per-test timeouts, retries, partitioning for CI and JUnit output; `cargo llvm-cov` for coverage via `-C instrument-coverage`; `rstest` for fixtures and parametrised cases, `mockall` or hand-written fakes behind traits (prefer fakes), `insta` for snapshot tests with `cargo insta review`',
      'Property tests: `proptest! { #[test] fn roundtrip(x in any::<u32>(), s in "[a-z]{1,8}") { prop_assert_eq!(..) } }` generates from strategies, shrinks failures to a minimal case and saves it in `proptest-regressions/` to commit; `quickcheck` is the simpler ancestor; `cargo fuzz` (libFuzzer, nightly) with `fuzz_target!(|data: &[u8]| ..)` and the `arbitrary` crate for structured input finds parser crashes that unit tests never will',
      'Benchmarks: `#[bench]` is nightly-only, so use `criterion` (`[[bench]] name = "x" harness = false`, `criterion_group!`/`criterion_main!`, `b.iter(|| f(black_box(input)))`, statistical comparison against the saved baseline, HTML reports) or `divan`; `std::hint::black_box` (1.66) stops the optimiser deleting the work; always `--release`, pin CPU frequency where you can, and use `iai-callgrind` instruction counts for noise-free CI comparisons',
    ],
    ['How do you test code that reads the clock or random numbers without feature flags?', 'Why might a criterion benchmark show a 5% improvement that production never sees?']),
  q('rust-performance-profiling', 'Memory and performance', 'medium', 'Performance and profiling: release profile, LTO, PGO, flamegraphs and allocation',
    'A Rust service is slower than expected. Explain the release profile and the flags that matter (`opt-level`, `lto`, `codegen-units`, `panic`, `debug`, `target-cpu`), PGO, how you profile (flamegraph, samply, perf, allocation profilers), the usual Rust-level causes, and how you verify a fix.',
    [
      'Debug builds are 10 to 100 times slower on iterator-heavy code (no inlining, overflow checks, debug assertions); `cargo build --release` sets `opt-level = 3`, no debuginfo, `codegen-units = 16`, thin local LTO, `panic = "unwind"`; `[profile.release] lto = "fat"` (or `"thin"`) and `codegen-units = 1` give 5 to 20% for longer compiles, `panic = "abort"` shrinks code, `debug = 1` keeps line tables so profiles have symbols, `strip = true` for shipping, `opt-level = "s"`/`"z"` for size',
      '`RUSTFLAGS="-C target-cpu=native"` enables AVX2 and friends for one machine (not for a portable binary; use `is_x86_feature_detected!` plus `#[target_feature(enable = "avx2")]` for runtime dispatch); PGO: build with `-Cprofile-generate=/tmp/pgo`, run a representative workload, `llvm-profdata merge`, rebuild with `-Cprofile-use`, or let `cargo pgo` drive it, typically 5 to 15% on branchy code; BOLT after that',
      'Profile first: `cargo flamegraph` (perf on Linux, dtrace on macOS) or `samply` (Firefox Profiler UI) for CPU; `perf stat` for IPC and cache misses; `valgrind --tool=dhat`, `heaptrack` or `dhat-rs` for allocation counts and sites; `tracing` spans with `tracing-timing`/`tokio-console` for async latency; `cargo bloat` and `cargo llvm-lines` when the problem is binary size or compile time from monomorphisation',
      'Usual causes: `clone()` of `String`/`Vec` in loops (take `&str`/`&[T]`, use `Cow`, `Rc<str>`, `bytes::Bytes`), `format!` where `write!` to a reused buffer would do, `collect` between stages, `HashMap` with SipHash on small keys (swap hasher or use a `Vec` index), `Box<dyn Trait>` in a hot loop, bounds checks from indexing (iterate instead), `Arc<Mutex<T>>` contention, unbuffered I/O (`BufReader`/`BufWriter`, `stdout().lock()`), and blocking the tokio runtime',
      'Allocator and memory: the system allocator is fine, but `mimalloc` or `tikv-jemallocator` as `#[global_allocator]` cuts multi-threaded allocation cost and fragmentation; `Vec::with_capacity`, `clear()` and reuse, `SmallVec`/`ArrayVec`, arenas (`bumpalo`, `typed-arena`, `slotmap`) for many short-lived nodes; `#[inline]` is needed for small non-generic functions to inline across crates without LTO',
      'Verify with the metric that defined the problem (p99 under load, throughput, RSS), not a microbenchmark; `criterion` or `hyperfine` for the isolated kernel; `cargo asm`/Godbolt to confirm vectorisation; keep a before/after flamegraph; and check that `--release` was actually what was deployed (a surprising number of slow Rust services were debug builds in a container)',
    ],
    ['Why can `lto = "fat"` make a binary slower to start or no faster at all, and what does `codegen-units = 1` trade?', 'How do you find who is allocating in a tokio service without stopping it?']),
  q('rust-api-design-idioms', 'API design', 'medium', 'API design idioms: newtype, builder, typestate, From/Into, AsRef and the API guidelines',
    'How do you design a Rust library API? Cover the newtype pattern, builders (owned versus `&mut self`), the typestate pattern, conversion traits (`From`/`Into`/`TryFrom`, `AsRef`, `Borrow`), which traits to derive, naming conventions, `#[must_use]`/`#[non_exhaustive]`, and what makes an API hard to evolve.',
    [
      'Newtype `struct UserId(u64)` is free at runtime and makes the compiler catch mixed-up ids, lets you implement foreign traits for foreign types (orphan rule), and hides representation; `#[repr(transparent)]` when it must cross FFI; implement `Display`, `From<u64>` deliberately, not `Deref` (reserved for smart pointers), and keep the inner field private unless construction must be open',
      'Builder: `Client::builder().timeout(d).retries(3).build()?`; an owned-`self` builder chains cleanly and allows one-shot construction, a `&mut self` builder suits conditional configuration; validate in `build()` returning `Result`; `derive_builder` or `bon` generate them; `Default` plus struct update syntax (`Config { port: 80, ..Default::default() }`) is enough for plain data',
      'Typestate: `Request<Unsent>` with `fn send(self) -> Request<Sent>` and methods available only on the right state, using zero-sized marker types and `PhantomData<S>`; the invalid call is a compile error with no runtime check, at the cost of more types and no dynamic state; use for protocols and resource handles, not for ordinary data',
      'Conversions: implement `From<X> for Y` and get `Into` free, so take `impl Into<String>` on constructors and return concrete types; `TryFrom` for fallible conversion with a real error type; `AsRef<str>`/`AsRef<Path>`/`AsRef<[u8]>` for parameters that only read (`fn open(p: impl AsRef<Path>)`); `Borrow` only for lookup keys where hash and equality must agree; `FromStr` for parsing; `Deref`/`DerefMut` only for smart pointers and newtypes that genuinely are the inner type',
      'Derive `Debug, Clone, PartialEq, Eq, Hash, Default` where they make sense (users cannot add them), `Copy` for small plain data, `PartialOrd, Ord` for keys, `serde` behind a feature; naming: `as_` (free borrow), `to_` (expensive or owned), `into_` (consumes), `iter`/`iter_mut`/`into_iter`, `is_`/`has_`, getters without `get_`; take `&[T]`/`&str`/`impl Iterator` not `&Vec`/`&String`; return `impl Iterator` or a named iterator type; errors as a public enum per module',
      'Evolvability: `#[non_exhaustive]` on enums and structs you may extend, `#[must_use]` on builders and pure functions, private fields with constructors, sealed traits (a hidden supertrait) when downstream impls would freeze your design, no `pub` dependency types in signatures unless re-exported with a feature; the Rust API Guidelines checklist (C-CONV, C-GETTER, C-COMMON-TRAITS, C-FEATURE) and `cargo-semver-checks` keep it honest',
    ],
    ['When does `impl Into<String>` on a parameter hurt (monomorphisation, inference) and what do you do instead?', 'Why should a public struct field almost never be a `Vec<T>` or `HashMap<K, V>` you intend to keep?']),
  q('rust-serde', 'Data handling', 'medium', 'Serde: the data model, derives, attributes and evolving payloads',
    'Explain how serde separates data formats from types (the data model, `Serialize`/`Deserialize`, visitors), the derive attributes you use most, how enums are represented, zero-copy deserialisation, dynamic `serde_json::Value`, and how to evolve a JSON payload without breaking old clients. Where does serde get slow or surprising?',
    [
      'Two traits, many formats: a type implements `Serialize`/`Deserialize` once against serde\'s 29-type data model (primitives, strings, bytes, option, unit, seq, tuple, map, struct, and the four enum variant shapes), and a format crate (`serde_json`, `toml`, `serde_yaml`, `bincode`, `postcard`, `rmp-serde`, `ciborium`) implements `Serializer`/`Deserializer`; deserialisation is pull-based through a `Visitor`, so no intermediate tree is built',
      '`#[derive(Serialize, Deserialize)]` (enable `features = ["derive"]`) with `#[serde(rename_all = "camelCase")]`, `rename`, `alias`, `default` (or `default = "fn"`), `skip`, `skip_serializing_if = "Option::is_none"`, `flatten` to inline a nested struct or capture extra fields into a `HashMap`, `deny_unknown_fields`, `with = "module"`/`serialize_with`/`deserialize_with` for custom formats, `try_from = "Raw"` to validate after parsing, `transparent` for newtypes',
      'Enums default to externally tagged (`{"Variant": {..}}`); `#[serde(tag = "type")]` internally tagged, `tag` plus `content` adjacently tagged, `untagged` tries each variant in order; untagged is slow (buffers the input and retries), gives useless errors ("did not match any variant") and silently picks the first matching variant, so prefer a tag when you control the format',
      'Zero-copy: `#[derive(Deserialize)] struct Msg<\'a> { #[serde(borrow)] name: &\'a str }` borrows from the input when the format supports it (`from_str`/`from_slice`, not `from_reader`) and the string has no escapes, else fails; `Cow<\'a, str>` with `borrow` takes either; `DeserializeOwned` is the bound for data that outlives the buffer; `serde_json::value::RawValue` defers parsing a sub-document',
      'Evolution: add fields as `Option<T>` or with `default`, never reorder a tuple struct, keep unknown fields ignored (the default) on the read side, rename with `alias` for the old name, version via a tagged enum when shapes diverge, and keep recorded fixtures in tests; integers: JSON numbers above 2^53 need strings or `arbitrary_precision`, `u64` to `f64` conversions lose precision, dates go through `chrono`/`time` `serde` features or `serde_with`',
      'Performance and surprises: `from_reader` is much slower than reading into a `Vec<u8>` then `from_slice`; `serde_json::Value` (dynamic, `Map` is a `BTreeMap` unless `preserve_order` enables `IndexMap`) is handy at boundaries and slow in loops; `simd-json`/`sonic-rs` for hot paths; derives dominate compile times for large schemas; `#[serde(flatten)]` disables some optimisations and breaks `deny_unknown_fields`; `HashMap<K, V>` with non-string keys cannot serialise to JSON maps without `serde_with`',
    ],
    ['How does serde handle a field that changed type from `u32` to `String` between versions?', 'Why does `#[serde(borrow)]` fail on a `from_reader` call?']),
  q('rust-axum-request-lifecycle', 'Frameworks', 'medium', 'Rust web services: the axum/tower/tokio request lifecycle',
    'Walk through a request in an axum service from `TcpListener` to response: tokio accept loop, hyper parsing, the tower `Service` and `Layer` middleware stack, routing, extractors, handler, `IntoResponse`, errors. Where do shared state, database pools, timeouts, tracing and graceful shutdown go, and what do you never do inside a handler?',
    [
      '`tokio::net::TcpListener::bind` plus `axum::serve(listener, app)`: the runtime accepts connections, spawns a task per connection, `hyper` (1.x) parses HTTP/1.1 or HTTP/2 frames and calls the `Router`, which is a tower `Service<Request<Body>>`; `tower::Service` is `poll_ready` then `call(req) -> Future<Output = Result<Response, Error>>`, and a `Layer` wraps one service in another',
      'Middleware order: `Router::layer` applies to the routes above it, and in a `ServiceBuilder` the first layer listed is outermost; `tower-http` supplies `TraceLayer` (a `tracing` span per request), `TimeoutLayer`, `CorsLayer`, `CompressionLayer`, `RequestBodyLimitLayer`, `SetRequestIdLayer`/`PropagateRequestIdLayer`; `tower` adds `ConcurrencyLimit`, `RateLimit`, `LoadShed`, `Buffer`; put request ids, tracing and timeouts outermost so every layer sees them; `axum::middleware::from_fn` for one-off async middleware',
      'Routing and handlers: `Router::new().route("/users/{id}", get(show).post(update))` (axum 0.8 switched `/:id` to `/{id}` and `*rest` to `{*rest}`); a handler is an `async fn` taking up to 16 extractors (`Path<u64>`, `Query<T>`, `State<AppState>`, `HeaderMap`, `Json<T>` last because it consumes the body) and returning anything `IntoResponse`; a wrong signature yields an opaque `Handler` trait error, which `#[axum::debug_handler]` turns into a real one',
      'State: `Router::with_state(AppState { pool, http: reqwest::Client, config: Arc<Config> })` where the struct is `Clone` and cheap (pools and clients are `Arc` inside), extracted with `State<AppState>` or `FromRef` for substates; `sqlx::PgPool` (compile-time checked `query!` with `DATABASE_URL` or offline `.sqlx` data), `deadpool`, `diesel-async`; one `reqwest::Client` reused for connection pooling, each outbound call with a timeout',
      'Errors: a `pub enum AppError` with `impl IntoResponse` mapping variants to status and a JSON body, `From` impls so handlers return `Result<Json<T>, AppError>` and use `?`; extractor rejections (bad JSON, missing path) are 4xx by default and customisable; log at the `TraceLayer`/error boundary with the request id, never in every layer; `tracing_subscriber` with `EnvFilter`, JSON output in production, `tracing-opentelemetry` for traces',
      'Never block in a handler (sync database drivers, `std::fs`, `std::thread::sleep`, CPU-heavy hashing like `argon2`): use `spawn_blocking` or a rayon pool; never hold a `std::sync::MutexGuard` across `.await`; set body limits and timeouts; shutdown with `axum::serve(..).with_graceful_shutdown(async { signal::ctrl_c().await })` so in-flight requests finish while the listener stops accepting; `actix-web` (own per-thread runtimes), `poem`, `rocket` are the alternatives, `tonic` for gRPC on the same tower stack',
    ],
    ['Why does a `Json<T>` extractor have to be the last argument of a handler?', 'How would you add per-tenant rate limiting as a tower layer rather than inside handlers?']),
  q('rust-editions-2024', 'Editions', 'medium', 'Editions and what Rust 2024 changed',
    'What is an edition, how can crates on different editions link together, and what did 2018, 2021 and 2024 each change? Go deep on 2024 (shipped in Rust 1.85): the `impl Trait` capture rules, `unsafe` attributes and `extern` blocks, `if let` temporary scopes, `static mut` references, the `gen` keyword, resolver 3, merged doc tests, and how `cargo fix --edition` migrates a crate.',
    [
      'An edition is a per-crate opt-in (`edition = "2024"` in `Cargo.toml`) that lets the language make breaking syntax and semantic changes without splitting the ecosystem: crates of any edition compile with the same compiler and interoperate, because editions change surface rules, not the ABI or the standard library; a new edition arrives roughly every three years and `cargo fix --edition` rewrites most code mechanically',
      '2018 (1.31): NLL borrow checking, the module path cleanup (`crate::`, no `extern crate`), `dyn Trait`, `async`/`await` reserved (stabilised 1.39), `?` in `main`; 2021 (1.56): disjoint closure captures, `IntoIterator` for arrays by value, `panic!` requiring a format string, or-patterns in `pat` fragments, `TryFrom`/`TryInto`/`FromIterator` in the prelude, resolver 2',
      '2024 (1.85, February 2025): return-position `impl Trait` captures all in-scope lifetimes (with `use<..>` to opt out); `#[unsafe(no_mangle)]`, `#[unsafe(export_name)]`, `#[unsafe(link_section)]`; `extern` blocks must be `unsafe extern`, and may mark items `safe`; `unsafe_op_in_unsafe_fn` warns by default; `static_mut_refs` denies `&STATIC_MUT`; `std::env::set_var`/`remove_var` are `unsafe fn`; `gen` is a reserved keyword (`r#gen`); `Box<[T]>` implements `IntoIterator` by value; the never type `!` fallback changed; `expr` fragments match `const {}` and `_`, with `expr_2021` for the old behaviour',
      'Temporary scopes in 2024: the temporaries in an `if let` scrutinee now drop before the `else` block runs (so a `RefCell` or `Mutex` borrow in the condition does not deadlock the else branch), and tail-expression temporaries drop before the block\'s locals, fixing the "borrowed value does not live long enough" at the end of functions returning `x.lock().unwrap().len()`-style expressions',
      'Tooling in 2024: cargo resolver `"3"` is MSRV-aware by default; `rustfmt` adopts a 2024 style edition (sorting imports by version-sort, among others); doc tests are merged into one binary per crate, cutting `cargo test --doc` time dramatically; `rustdoc` nested `include_str!`; let chains (`if let .. && let ..`) stabilised in 1.88 only for edition 2024 because of the temporary-scope change',
      'Migration: `cargo fix --edition` applies the compatibility lints (`rust_2024_compatibility`) on the old edition, then you bump `edition`, run `cargo fix --edition-idioms`, and fix the handful of places that need judgement (precise capturing `use<>`, `unsafe` blocks inside `unsafe fn`); do it per crate, not per workspace, and keep `rust-version` in step because 2024 needs 1.85',
    ],
    ['Why can the standard library not change behaviour per edition, and how did `IntoIterator` for arrays work around that in 2021?', 'What does the RPIT capture change break in a function returning `impl Iterator` that borrows two parameters with different lifetimes?']),
  q('rust-when-wrong-tool-interop', 'Judgement', 'easy', 'When Rust is the wrong tool, and interop with existing systems',
    'When would you advise against Rust for a project, and when is it the right call? How do you introduce Rust into an existing Python, Node, Ruby, JVM, C/C++ or mobile codebase without a rewrite, which bridges exist, and what do you tell a team about compile times, hiring and the learning curve?',
    [
      'Wrong tool when: the problem is dominated by iteration speed and the team is new to Rust (prototypes, internal CRUD, data exploration), when a garbage collector would simplify the domain (highly cyclic graphs, GUI object trees, interpreters with shared mutable state), when the ecosystem is thin (desktop GUI is improving but still behind, some ML tooling), or when compile times would block a tight edit-test loop on a huge monolith',
      'Right tool when: latency tails, memory footprint or throughput per core matter (proxies, databases, search, game engines, browsers), when safety without GC pauses is required (embedded, kernels, firmware, WebAssembly), when a long-lived service must be correct under concurrency, or when C/C++ would otherwise be chosen; the Linux kernel (6.1), Android, Windows and Chromium all accept Rust for new components',
      'Hot-kernel strategy: keep the application and move the measured bottleneck into a Rust module exposed natively: `PyO3` plus `maturin` for Python (`polars`, `pydantic-core`, `ruff` did this), `napi-rs` or `neon` for Node (`swc`, `oxc`, `rspack`), `magnus`/`rb-sys` for Ruby gems, `jni`/`UniFFI`/`JNI` for the JVM and Kotlin, `UniFFI` or `swift-bridge` for iOS and Android, `wasm-bindgen`/`wasm-pack` for the browser',
      'C and C++: a plain C ABI (`extern "C"`, `#[repr(C)]`, `cbindgen`) works everywhere; `bindgen` consumes C headers, `cxx` gives a type-checked C++ bridge (`CxxString`, `UniquePtr`, shared structs) without hand-written unsafe; `autocxx` automates more; `cargo` can drive `cc`/`cmake` builds through `build.rs`, and Rust can be a static library linked into an existing CMake or Bazel project',
      'Team realities: compile times are the main complaint (mitigate with `cargo check`, incremental builds, `sccache`, `mold`/`lld` as the linker on Linux, where `rust-lld` became the default for x86_64 in 1.90, splitting crates, `cargo nextest`, fewer heavy derives); a productive engineer in weeks, fluent in months, with the borrow checker and async as the two humps; hiring is easier than it was, and most Rust hires are trained internally from C++, Go, TypeScript or Python backgrounds',
      'Argue with numbers: a bakeoff on the real hot path (p99, memory, cost per request) and a one-service pilot with an exit plan, not a language debate; the first Rust service needs owned CI (toolchain pin, clippy, `cargo deny`), an on-call team that can read it, and an interop boundary thin enough to remove if the pilot fails',
    ],
    ['What are the risks of a Python extension in Rust (GIL handling, panics, ABI versions) and how does PyO3 address them?', 'How does WebAssembly change the calculus for shipping Rust to the browser or to a plugin system?']),
  q('rust-compile-times-dev-workflow', 'Modules and tooling', 'medium', 'Compile times, incremental builds and the development workflow',
    'Rust builds are slow and the team is frustrated. Explain where compile time goes (frontend, monomorphisation, LLVM, linking), how incremental compilation and `cargo check` help, the levers (crate splitting, fewer generics and derives, `sccache`, faster linkers, the cranelift backend, dependency hygiene), and the day-to-day toolchain: rust-analyzer, clippy, rustfmt, `cargo nextest`, `cargo watch`/`bacon`.',
    [
      'Where time goes: parsing and type checking are fast; trait solving and macro expansion (`syn`-heavy derives) can dominate `cargo check`; monomorphisation multiplies generic code per instantiation and LLVM optimisation of that code dominates release builds; linking a large binary with the system linker dominates incremental debug builds; `cargo build --timings` shows the per-crate critical path and `-Zself-profile` the passes',
      'Incremental compilation (on in `dev`, off in `release` by default) reuses unchanged codegen units; `cargo check` stops after type checking and is what the editor should run; `codegen-units = 256` default for dev; keep dev builds fast by setting `[profile.dev.package."*"] opt-level = 3` so dependencies are optimised once and your code stays unoptimised, or `[profile.dev] opt-level = 1` when debug is too slow to test',
      'Structure: split a large crate into workspace members so cargo compiles them in parallel and recompiles only what changed; move generic-heavy code behind a non-generic inner function (`fn inner(s: &str)` called from `fn outer(s: impl AsRef<str>)`); prefer `dyn` where the hot path does not care; audit `cargo tree` for duplicate versions and `cargo bloat --time`/`cargo llvm-lines` for which functions instantiate most; trim feature flags (`tokio` with only needed features, `serde_json` without `preserve_order`), drop `syn` `full` where not needed',
      'Toolchain levers: `sccache` or `cargo` with a shared `target-dir` and CI cache keyed on `Cargo.lock`; a faster linker (`mold` or `lld`; `rust-lld` is the default on x86_64 Linux since 1.90) through `.cargo/config.toml` `rustflags = ["-C", "link-arg=-fuse-ld=mold"]`; the cranelift backend for debug builds (`-Zcodegen-backend=cranelift`, nightly, shipped as a rustup component); `debug = "line-tables-only"` to shrink debuginfo; `split-debuginfo = "unpacked"` on macOS',
      'Daily loop: rust-analyzer runs `cargo check` (or `clippy`) on save with inline diagnostics and type hints; `bacon` or `cargo watch -x check -x test` in a terminal; `cargo nextest run` for faster, isolated tests; `cargo clippy --all-targets -- -D warnings` with a curated `[lints]` table (`clippy::pedantic` selectively, `unwrap_used` in services), `cargo fmt --check` in CI; `cargo doc --open` to read your own API as users see it; `cargo expand` for macro debugging',
      'Set expectations: a clean release build of a 500-crate graph is minutes, incremental debug rebuilds should be seconds; if they are not, the critical path is usually one giant crate, one procedural macro crate rebuilt often, or the linker; measure with `--timings` before reorganising, and do not trade runtime performance (`opt-level`, LTO) in the shipped profile to win developer time, keep separate profiles',
    ],
    ['Why does changing one line in a leaf crate sometimes rebuild half the workspace, and what does `cargo build --timings` show you?', 'When does `dyn Trait` reduce compile time without a measurable runtime cost?']),
]
